5	
6	@import url("tokens.css");
7	
8	* { box-sizing: border-box; margin: 0; padding: 0; }
9	
10	body {
11	  font-family: var(--font-sans);
12	  background: #1a1a2e;
13	  display: flex;
14	  align-items: center;
15	  justify-content: center;
16	  min-height: 100vh;
17	  -webkit-font-smoothing: antialiased;
18	  text-rendering: optimizeLegibility;
19	}
20	
21	/* ---- The watch canvas ---- */
22	.watch {
23	  position: relative;
24	  width: var(--watch-size);
25	  height: var(--watch-size);
26	  border-radius: var(--watch-radius);
27	  overflow: hidden;
28	  background: var(--bg-base);
29	  box-shadow:
30	    0 0 0 var(--bezel-width) #0a0a14,
31	    0 0 0 calc(var(--bezel-width) + 2px) #1c1c2e,
32	    0 0 0 calc(var(--bezel-width) + 4px) #050509,
33	    0 30px 80px rgba(0, 0, 0, 0.7);
34	}
35	
36	/* ---- Screen content sits inside the circle ---- */
37	.screen {
38	  position: absolute;
39	  inset: 0;
40	  display: flex;
41	  flex-direction: column;
42	  align-items: center;
43	  color: var(--text-primary);
44	}
45	
46	/* ---- Status bar (top) ---- */
47	.statusbar {
48	  position: absolute;
49	  top: 30px;
50	  left: 0;
51	  right: 0;
52	  display: flex;
53	  align-items: center;
54	  justify-content: center;
55	  gap: 6px;
56	  font-size: 13px;
57	  color: var(--text-secondary);
58	  z-index: 5;
59	}
60	.statusbar .time { font-family: var(--font-num); font-weight: 600; }
61	
62	/* ---- Status pill ---- */
63	.status-pill {
64	  display: inline-flex;
65	  align-items: center;
66	  gap: 8px;
67	  padding: 7px 16px;
68	  border-radius: var(--r-pill);
69	  font-size: 14px;
70	  font-weight: 600;
71	  letter-spacing: 0.5px;
72	  background: var(--bg-card);
73	  backdrop-filter: blur(10px);
74	  border: 1px solid var(--stroke-soft);
75	}
76	.status-pill .dot {
77	  width: 8px;
78	  height: 8px;
79	  border-radius: 50%;
80	  flex-shrink: 0;
81	}
82	.status-pill .dot.pulse { animation: pulse 1.4s ease-in-out infinite; }
83	
84	.status-pill.connecting { color: var(--status-connecting); border-color: rgba(255,165,2,0.35); background: rgba(255,165,2,0.10); }
85	.status-pill.ready      { color: var(--status-ready); border-color: rgba(38,222,129,0.35); background: rgba(38,222,129,0.10); }
86	.status-pill.listening  { color: var(--status-listening); border-color: rgba(0,206,201,0.35); background: rgba(0,206,201,0.10); }
87	.status-pill.recognizing { color: var(--status-recognizing); border-color: rgba(108,92,231,0.40); background: rgba(108,92,231,0.12); }
88	
89	/* ---- Talk / mic button ---- */
90	.talk-btn {
91	  position: relative;
92	  width: 132px;
93	  height: 132px;
94	  border-radius: 50%;
95	  border: none;
96	  background: linear-gradient(145deg, var(--brand-primary), #4a3fbf);
97	  color: var(--text-on-brand);
98	  display: flex;
99	  align-items: center;
100	  justify-content: center;
101	  cursor: pointer;
102	  box-shadow: var(--glow-brand), inset 0 2px 4px rgba(255,255,255,0.2), inset 0 -4px 8px rgba(0,0,0,0.3);
103	  transition: transform var(--dur-fast) var(--ease-spring), box-shadow var(--dur-fast) var(--ease-out);
104	}
105	.talk-btn:active { transform: scale(0.94); }
106	.talk-btn svg { width: 52px; height: 52px; }
107	
108	/* Ripple rings around talk button when active */
109	.talk-btn .ripple {
110	  position: absolute;
111	  inset: 0;
112	  border-radius: 50%;
113	  border: 2px solid var(--brand-primary);
114	  opacity: 0;
