137	/* ---- Animations ---- */
138	@keyframes pulse {
139	  0%, 100% { opacity: 1; transform: scale(1); }
140	  50% { opacity: 0.4; transform: scale(1.3); }
141	}
142	@keyframes ripple {
143	  0% { transform: scale(1); opacity: 0.7; }
144	  100% { transform: scale(1.7); opacity: 0; }
145	}
146	@keyframes float-up {
147	  from { opacity: 0; transform: translateY(12px); }
148	  to { opacity: 1; transform: translateY(0); }
149	}
150	@keyframes spin { to { transform: rotate(360deg); } }
