        lv_async_call(run_distry, NULL);
    }
    LV_LOG_USER("timer_cul_cb  %d  %d", timerControlObj->ms, timerControlObj->curms);
    LV_LOG_USER("timer_cul_cb  %d", timerControlObj->curms * 90 / timerControlObj->ms);
}

