118	    lv_obj_set_style_text_font(ui_names[idx], font_manager_get_font(FONT_LARGE), 0);  /* 中文 24 号 */
119	    lv_obj_align(ui_names[idx], LV_ALIGN_LEFT_MID, 80, 0);
120	
121	    lv_obj_add_event_cb(ui_cards[idx], card_event_cb, LV_EVENT_ALL, (void*)(intptr_t)idx);
122	}
123	
124	/* ========== 卡片样式：默认态 / 按下态 ==========
125	 * 默认低亮；按下(PRESSED)给高亮反馈，松开(RELEASED)还原——不保留持续高亮。 */
126	static void set_card_default(int8_t i)
127	{
128	    lv_obj_set_style_border_color(ui_cards[i], COLOR_PURPLE, 0);
129	    lv_obj_set_style_border_width(ui_cards[i], 2, 0);
130	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_PURPLE, 0);
131	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_10, 0);
132	    lv_obj_set_style_text_color(ui_icons[i], COLOR_PURPLE, 0);
133	    lv_obj_set_style_text_color(ui_names[i], COLOR_GRAY, 0);
134	}
135	
136	static void set_card_pressed(int8_t i)
137	{
138	    lv_obj_set_style_border_color(ui_cards[i], COLOR_CYAN, 0);
139	    lv_obj_set_style_border_width(ui_cards[i], 3, 0);
140	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_CYAN, 0);
141	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_30, 0);
142	    lv_obj_set_style_text_color(ui_icons[i], COLOR_CYAN, 0);
143	    lv_obj_set_style_text_color(ui_names[i], COLOR_WHITE, 0);
144	}
145	
146	static void card_event_cb(lv_event_t *e)
147	{
148	    lv_event_code_t code = lv_event_get_code(e);
149	    int8_t idx = (int8_t)(intptr_t)lv_event_get_user_data(e);
150	    if (code == LV_EVENT_PRESSED) {
151	        set_card_pressed(idx);        /* 按下即高亮 */
152	    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
153	        set_card_default(idx);        /* 松开/失去按下即还原 */
154	    } else if (code == LV_EVENT_CLICKED) {
155	        if (apps[idx].launch_cb) apps[idx].launch_cb();
156	    }
157	}
158	
159	/* ========== 公开API ========== */
160	void app_launcher_create(lv_obj_t *parent)
161	{
162	    /* parent == 调用方传入的 appListCenter：设成铺满 watchScr、透明、不裁剪，
163	     * 让 455×455 的圆形 ui_bg 能正确居中，并配合 watch_start.c 的滑入动画（translate_y 作用于 parent）。 */
164	    lv_obj_set_size(parent, SCREEN_W, SCREEN_H);
165	    lv_obj_align(parent, LV_ALIGN_CENTER, 0, 0);
166	    lv_obj_set_style_bg_opa(parent, LV_OPA_TRANSP, 0);
167	    lv_obj_set_style_border_width(parent, 0, 0);
168	    lv_obj_set_style_pad_all(parent, 0, 0);
169	    lv_obj_clear_flag(parent, LV_OBJ_FLAG_SCROLLABLE);
170	
171	    create_background(parent);
172	    create_title();
173	    for (int8_t i = 0; i < APP_COUNT; i++) create_app_card(i);
174	    /* 初始全部默认态（不预选高亮） */
175	    for (int8_t i = 0; i < APP_COUNT; i++) set_card_default(i);
176	    selected_idx = 0;
177	    ui_group = lv_group_create();
178	    for (int8_t i = 0; i < APP_COUNT; i++) lv_group_add_obj(ui_group, ui_cards[i]);
179	}
180	
181	void app_launcher_next(void)  { selected_idx = (selected_idx+1) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
182	void app_launcher_prev(void)  { selected_idx = (selected_idx-1+APP_COUNT) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
183	void app_launcher_enter(void) { if (apps[selected_idx].launch_cb) apps[selected_idx].launch_cb(); }
184	int8_t app_launcher_get_selected(void) { return selected_idx; }
185	lv_group_t *app_launcher_get_group(void) { return ui_group; }
186	
187	void app_launcher_delete(void)
188	{
189	    if (ui_group) { lv_group_del(ui_group); ui_group = NULL; }
190	    if (ui_bg) { lv_obj_del(ui_bg); ui_bg = NULL; }
191	    /* 清空卡片/图标/名称数组引用，防悬空指针 */
192	    for (int8_t i = 0; i < APP_COUNT; i++) {
193	        ui_cards[i] = NULL; ui_icons[i] = NULL; ui_names[i] = NULL;
194	    }
195	    ui_ring = NULL; ui_title = NULL;
196	    selected_idx = 0;
197	}
198	
199	/* ========== 旧 API 适配：供 watch_start.c 页面栈调用 ==========
200	 * applist_create_list: 左滑/返回时建列表，内部委托 app_launcher_create。
201	 * applist_hide_page:   右滑/进二级页删列表前清理静态引用（group + ui_bg 子树），
202	 *                      调用方随后 lv_obj_delete(appListCenter) 删容器壳。 */
203	lv_obj_t *applist_create_list(lv_obj_t *scr)
204	{
205	    app_launcher_create(scr);
206	    return scr;
207	}
208	
209	void applist_hide_page(void)
210	{
211	    app_launcher_delete();  /* 删 group + ui_bg 子树，清空静态指针 */
212	    LV_LOG_USER("applist_hide_page: launcher cleaned");
213	}

